using System.Security.Cryptography;
using static DotReticulum.Transport.Tests.Parity5ChannelTests;

namespace DotReticulum.Transport.Tests;

// Buffer.py at a29bfb51c468945c96a1ee22cae0114e993e2391.
// Fixtures are independent Python executions, not bytes generated by this library.
public sealed class Parity5ChannelBufferTests
{
    private static void ReceiveStream(Channel channel, int sequence, byte[] data, bool eof = false, int stream = 7) =>
        channel.Receive(Raw(sequence, new StreamDataMessage(stream, data, eof).Pack(), StreamDataMessage.StreamDataMsgType));

    [Fact]
    public void StreamHeadersCompressedChunkBoundaryAndExpansionRejectionMatchReference()
    {
        foreach (var vector in Vectors.GetProperty("streams").EnumerateArray())
        {
            var raw = Convert.FromHexString(vector.GetProperty("raw").GetString()!);
            var message = new StreamDataMessage();
            message.Unpack(raw);
            Assert.Equal(vector.GetProperty("id").GetInt32(), message.StreamId);
            Assert.Equal(vector.GetProperty("eof").GetBoolean(), message.Eof);
            Assert.Equal(vector.GetProperty("compressed").GetBoolean(), message.Compressed);
            Assert.Equal(Convert.FromHexString(vector.GetProperty("data").GetString()!), message.Data);
            if (!message.Compressed) Assert.Equal(raw, message.Pack());
        }
        var oversized = Convert.FromHexString(Vectors.GetProperty("oversizedCompressedChunk").GetProperty("raw").GetString()!);
        Assert.Throws<InvalidDataException>(() => new StreamDataMessage().Unpack(oversized));
        Assert.Throws<IOException>(() => new StreamDataMessage().Unpack([]));
        Assert.Throws<IOException>(() => new StreamDataMessage().Unpack([0]));
    }

    [Fact]
    public async Task ReaderUsesBoundedCircularStorageAcrossPartialReadsAndWrap()
    {
        var channel = new Channel(new Outlet());
        using var reader = new RawChannelReader(7, channel, maxBufferedBytes: 4);
        ReceiveStream(channel, 0, [1, 2, 3]);
        var first = new byte[2];
        Assert.Equal(2, await reader.ReadAsync(first));
        Assert.Equal(new byte[] { 1, 2 }, first);
        ReceiveStream(channel, 1, [4, 5, 6], eof: true);
        Assert.Equal(4, reader.Available);
        var rest = new byte[9];
        Assert.Equal(4, await reader.ReadAsync(rest));
        Assert.Equal(new byte[] { 3, 4, 5, 6 }, rest[..4]);
        Assert.Equal(0, await reader.ReadAsync(rest));
        Assert.True(reader.EndOfStream);
        ReceiveStream(channel, 2, [7, 8]);
        Assert.Equal(0, reader.Available);
    }

    [Fact]
    public async Task SlowConsumerOverflowFailsClosedAndDoesNotReturnSilentTruncation()
    {
        var outlet = new Outlet();
        var channel = new Channel(outlet);
        using var reader = new RawChannelReader(7, channel, maxBufferedBytes: 4);
        ReceiveStream(channel, 0, [1, 2, 3]);
        ReceiveStream(channel, 1, [4, 5]);
        Assert.Equal(0, reader.Available);
        Assert.Equal(1, outlet.Teardowns);
        Assert.True(channel.Completion.IsCompletedSuccessfully);
        var failure = await Assert.ThrowsAsync<IOException>(() => reader.ReadAsync(new byte[1]).AsTask());
        Assert.Contains("unread buffer limit", failure.Message);
        Assert.Contains(outlet.Logs, text => text.Contains("4-byte", StringComparison.Ordinal));
    }

    [Fact]
    public async Task OversizedFirstChunkWakesBlockedReadWithExplicitFailure()
    {
        var channel = new Channel(new Outlet());
        using var reader = new RawChannelReader(7, channel, maxBufferedBytes: 1);
        var pending = reader.ReadAsync(new byte[1]).AsTask();
        ReceiveStream(channel, 0, [1, 2]);
        await Assert.ThrowsAsync<IOException>(() => pending.WaitAsync(TimeSpan.FromSeconds(5)));
    }

    [Fact]
    public async Task PendingReadIsReleasedByDisposeAndSubsequentReadsRemainDisposed()
    {
        var reader = new RawChannelReader(7, new Channel(new Outlet()));
        var pending = reader.ReadAsync(new byte[1]).AsTask();
        Assert.False(pending.IsCompleted);
        reader.Dispose();
        await Assert.ThrowsAsync<ObjectDisposedException>(() => pending.WaitAsync(TimeSpan.FromSeconds(5)));
        await Assert.ThrowsAsync<ObjectDisposedException>(() => reader.ReadAsync(new byte[1]).AsTask());
        Assert.False(reader.CanRead);
    }

    [Fact]
    public async Task LinkClosureCompletesPendingReadAndDrainsAlreadyBufferedBytesFirst()
    {
        var channel = new Channel(new Outlet());
        using var reader = new RawChannelReader(7, channel);
        var pending = reader.ReadAsync(new byte[3]).AsTask();
        ReceiveStream(channel, 0, [1, 2, 3]);
        Assert.Equal(3, await pending.WaitAsync(TimeSpan.FromSeconds(5)));
        ReceiveStream(channel, 1, [4, 5]);
        channel.Shutdown();
        Assert.True(reader.EndOfStream);
        var bytes = new byte[3];
        Assert.Equal(2, await reader.ReadAsync(bytes));
        Assert.Equal(new byte[] { 4, 5 }, bytes[..2]);
        Assert.Equal(0, await reader.ReadAsync(bytes));

        var emptyChannel = new Channel(new Outlet());
        using var empty = new RawChannelReader(7, emptyChannel);
        var blocked = empty.ReadAsync(new byte[1]).AsTask();
        emptyChannel.Shutdown();
        Assert.Equal(0, await blocked.WaitAsync(TimeSpan.FromSeconds(5)));
    }

    [Fact]
    public async Task ReadCancellationAndZeroLengthDoNotConsumeDataOrSignalEof()
    {
        var channel = new Channel(new Outlet());
        using var reader = new RawChannelReader(7, channel);
        Assert.Equal(0, await reader.ReadAsync(Memory<byte>.Empty));
        using var cancellation = new CancellationTokenSource();
        var pending = reader.ReadAsync(new byte[1], cancellation.Token).AsTask();
        cancellation.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => pending);
        Assert.False(reader.EndOfStream);
        ReceiveStream(channel, 0, [1]);
        Assert.Equal(0, await reader.ReadAsync(Memory<byte>.Empty));
        Assert.Equal(1, reader.Available);
        Assert.Equal(1, await reader.ReadAsync(new byte[1]));
    }

    [Fact]
    public async Task ReadyCallbackFailuresAreLoggedAndDoNotDisableOtherCallbacksOrReads()
    {
        var outlet = new Outlet();
        var channel = new Channel(outlet);
        using var reader = new RawChannelReader(7, channel);
        var seen = 0;
        reader.AddReadyCallback(_ => throw new InvalidOperationException("ready observer marker"));
        reader.AddReadyCallback(ready => seen = ready);
        ReceiveStream(channel, 0, [1, 2, 3], eof: true);
        await reader.ReadyCallbacksCompletion.WaitAsync(TimeSpan.FromSeconds(5));
        Assert.Equal(3, seen);
        Assert.Contains(outlet.Logs, text => text.Contains("ready observer marker", StringComparison.Ordinal)
            && text.Contains("stream 7", StringComparison.Ordinal));
        Assert.Equal(3, await reader.ReadAsync(new byte[4]));
        Assert.Equal(0, await reader.ReadAsync(new byte[4]));
    }

    [Fact]
    public async Task SlowReadyCallbackHasOnlyOneWorkerAndOneCoalescedNotification()
    {
        var channel = new Channel(new Outlet());
        using var reader = new RawChannelReader(7, channel);
        var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var release = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var calls = 0;
        reader.AddReadyCallback(_ =>
        {
            if (Interlocked.Increment(ref calls) == 1)
            {
                entered.TrySetResult();
                release.Task.GetAwaiter().GetResult();
            }
        });
        try
        {
            ReceiveStream(channel, 0, [0]);
            await entered.Task.WaitAsync(TimeSpan.FromSeconds(5));
            var owned = reader.ReadyCallbacksCompletion;
            for (var sequence = 1; sequence <= 100; sequence++) ReceiveStream(channel, sequence, [1]);
            Assert.Same(owned, reader.ReadyCallbacksCompletion);
            Assert.Equal(1, Volatile.Read(ref calls));
            Assert.Equal(101, reader.Available);
        }
        finally
        {
            release.TrySetResult();
            await reader.ReadyCallbacksCompletion.WaitAsync(TimeSpan.FromSeconds(5));
        }
        Assert.Equal(2, calls);
    }

    [Fact]
    public async Task ReadyCallbackCanDisposeItsOwnReaderWithoutDeadlockOrLaterCallbacks()
    {
        var channel = new Channel(new Outlet());
        var reader = new RawChannelReader(7, channel);
        var later = 0;
        reader.AddReadyCallback(_ => reader.Dispose());
        reader.AddReadyCallback(_ => Interlocked.Increment(ref later));
        ReceiveStream(channel, 0, [1]);
        await reader.ReadyCallbacksCompletion.WaitAsync(TimeSpan.FromSeconds(5));
        Assert.False(reader.CanRead);
        Assert.Equal(0, later);
        ReceiveStream(channel, 1, [2]);
        Assert.Equal(0, reader.Available);
    }

    [Fact]
    public async Task StalledOptionalChannelObserverDoesNotBlockStreamProtocolOrReaderDisposal()
    {
        var channel = new Channel(new Outlet());
        channel.RegisterMessageType<BytesMessage>();
        var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var release = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        channel.AddMessageHandler(_ =>
        {
            entered.TrySetResult();
            release.Task.GetAwaiter().GetResult();
            return false;
        });
        using var reader = new RawChannelReader(7, channel);
        try
        {
            channel.Receive(Raw(0));
            await entered.Task.WaitAsync(TimeSpan.FromSeconds(5));
            ReceiveStream(channel, 1, [1, 2, 3], eof: true);
            var bytes = new byte[3];
            Assert.Equal(3, await reader.ReadAsync(bytes).AsTask().WaitAsync(TimeSpan.FromSeconds(5)));
            Assert.Equal(new byte[] { 1, 2, 3 }, bytes);
            Assert.Equal(0, await reader.ReadAsync(bytes));
            reader.Dispose();
        }
        finally
        {
            release.TrySetResult();
            await channel.HandlerCompletion.WaitAsync(TimeSpan.FromSeconds(5));
        }
    }

    [Fact]
    public async Task ConcurrentWriteAndCloseWaitForBackpressureAndEmitOnlyOneFinalEof()
    {
        var outlet = new Outlet();
        var channel = new Channel(outlet);
        var writer = new RawChannelWriter(7, channel);
        try
        {
            var payload = RandomNumberGenerator.GetBytes(4000);
            var writing = writer.WriteAsync(payload).AsTask();
            Assert.False(writing.IsCompleted);
            var closing = writer.CloseAsync();
            Assert.Same(closing, writer.CloseAsync());
            Assert.Throws<ObjectDisposedException>(() => writer.WriteChunk([1]));
            Volatile.Write(ref outlet.AutoDeliver, true);
            foreach (var receipt in outlet.Receipts) Outlet.Deliver(receipt);
            await Task.WhenAll(writing, closing).WaitAsync(TimeSpan.FromSeconds(5));
            var decoded = outlet.Sent.Select(raw =>
            {
                var message = new StreamDataMessage();
                message.Unpack(raw.AsSpan(6));
                return message;
            }).ToArray();
            Assert.True(decoded[^1].Eof);
            Assert.Equal(1, decoded.Count(message => message.Eof));
            Assert.Empty(decoded[^1].Data);
            Assert.Equal(payload, decoded.SelectMany(message => message.Data).ToArray());
            Assert.False(writer.CanWrite);
        }
        finally
        {
            channel.Shutdown();
            await writer.DisposeAsync();
        }
    }

    [Fact]
    public async Task CanceledCloseCanRetryWithoutLosingOrDuplicatingEof()
    {
        var outlet = new Outlet();
        var channel = new Channel(outlet);
        channel.Send(new BytesMessage());
        channel.Send(new BytesMessage());
        var writer = new RawChannelWriter(7, channel);
        try
        {
            using var cancellation = new CancellationTokenSource();
            var closing = writer.CloseAsync(cancellation.Token);
            cancellation.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => closing);
            Volatile.Write(ref outlet.AutoDeliver, true);
            foreach (var receipt in outlet.Receipts) Outlet.Deliver(receipt);
            await writer.CloseAsync().WaitAsync(TimeSpan.FromSeconds(5));
            Assert.Equal(3, outlet.Sent.Count);
            var eof = new StreamDataMessage();
            eof.Unpack(outlet.Sent.Last().AsSpan(6));
            Assert.True(eof.Eof);
            await writer.CloseAsync();
            Assert.Equal(3, outlet.Sent.Count);
        }
        finally
        {
            channel.Shutdown();
            await writer.DisposeAsync();
        }
    }

    [Fact]
    public async Task ShutdownReleasesBlockedWriterAndCloseWithoutSendingPostCloseEof()
    {
        var outlet = new Outlet();
        var channel = new Channel(outlet);
        channel.Send(new BytesMessage());
        channel.Send(new BytesMessage());
        var writer = new RawChannelWriter(7, channel);
        var writing = writer.WriteAsync(new byte[] { 1 }).AsTask();
        var closing = writer.CloseAsync();
        channel.Shutdown();
        await Assert.ThrowsAsync<IOException>(() => writing.WaitAsync(TimeSpan.FromSeconds(5)));
        await closing.WaitAsync(TimeSpan.FromSeconds(5));
        Assert.Equal(2, outlet.Sent.Count);
        await writer.DisposeAsync();
    }

    [Theory]
    [InlineData(431)]
    [InlineData(16000)]
    [InlineData(262000)]
    public async Task NegotiatedMduControlsPayloadBudgetWhileDecodedChunksStayWithin16KiB(int mdu)
    {
        var outlet = new Outlet { Mdu = mdu, AutoDeliver = true };
        var channel = new Channel(outlet);
        var writer = new RawChannelWriter(7, channel);
        var input = RandomNumberGenerator.GetBytes(RawChannelWriter.MaxChunkLength * 2 + 73);
        await writer.WriteAsync(input);
        await writer.CloseAsync();
        var received = new List<byte>();
        foreach (var raw in outlet.Sent)
        {
            Assert.InRange(raw.Length, 8, mdu);
            var message = new StreamDataMessage();
            message.Unpack(raw.AsSpan(6));
            Assert.InRange(message.Data.Length, 0, RawChannelWriter.MaxChunkLength);
            received.AddRange(message.Data);
        }
        Assert.Equal(input, received.ToArray());
        channel.Shutdown();
        await writer.DisposeAsync();
    }

    [Fact]
    public void StreamIdsBufferBoundsAndCallbackRegistrationsAreValidated()
    {
        var channel = new Channel(new Outlet());
        Assert.Throws<ArgumentOutOfRangeException>(() => new RawChannelReader(-1, channel));
        Assert.Throws<ArgumentOutOfRangeException>(() => new RawChannelWriter(16384, channel));
        Assert.Throws<ArgumentOutOfRangeException>(() => new RawChannelReader(7, channel, maxBufferedBytes: 0));
        using var reader = new RawChannelReader(7, channel);
        for (var i = 0; i < RawChannelReader.MaximumReadyCallbacks; i++) reader.AddReadyCallback(_ => { });
        Assert.Throws<InvalidOperationException>(() => reader.AddReadyCallback(_ => { }));
    }
}
